(function(){
var cv=document.getElementById('canvas'),ctx=cv.getContext('2d');
var W=cv.width,H=cv.height;
var st=document.getElementById('game-status');
var btn=document.getElementById('start-game');
var elL=document.getElementById('level'),elS=document.getElementById('score'),elV=document.getElementById('lives');
var LEVELS=[
['1111111111','1111111111','1111111111'],
['1010101010','0101010101','1010101010','0101010101'],
['0001111000','0011111100','0111111110','1111111111'],
['1111111111','1000000001','1011111101','1010000101','1011111101'],
['2222222222','1111111111','2020202020','1111111111','2222222222']
];
var COLORS=['','#ef476f','#06d6a0'];
var RC=['#ef476f','#ffd166','#06d6a0','#118ab2','#c77dff'];
var paddle,ball,bricks,level,score,lives,state='idle',running=false,raf=0,keys={left:false,right:false};
function setStatus(s,t){st.setAttribute('data-state',s);st.textContent=t;}
function hud(){elL.textContent=level+1;elS.textContent=score;elV.textContent=lives;}
function buildLevel(n){
 bricks=[];var rows=LEVELS[n],bw=44,bh=18,gap=4,cols=10;
 var ox=(W-(cols*(bw+gap)-gap))/2;
 for(var r=0;r<rows.length;r++)for(var c=0;c<cols;c++){
  var v=parseInt(rows[r][c],10);
  if(v>0)bricks.push({x:ox+c*(bw+gap),y:50+r*(bh+gap),w:bw,h:bh,hp:v,row:r});
 }
}
function resetBall(){
 paddle.x=W/2-paddle.w/2;
 ball={x:W/2,y:H-40,r:7,vx:0,vy:0,stuck:true};
}
function newGame(){
 level=0;score=0;lives=3;
 paddle={w:84-0,h:12,x:W/2-42,y:H-24};
 buildLevel(0);resetBall();hud();
}
function launch(){
 if(state!=='playing'||!ball.stuck)return;
 var sp=3.2+level*0.35;
 var a=(-60+Math.random()*-60)*Math.PI/180;
 ball.vx=Math.cos(a)*sp;ball.vy=Math.sin(a)*sp;ball.stuck=false;
 setStatus('playing','Spelet pågår – krossa alla klossar! Bana '+(level+1));
}
function start(){
 newGame();state='playing';
 setStatus('playing','Spelet pågår – klicka eller tryck mellanslag för att skjuta iväg bollen.');
 btn.textContent='Starta om';
 if(!running){running=true;raf=requestAnimationFrame(loop);}
}
function movePaddleTo(px){
 paddle.x=Math.max(0,Math.min(W-paddle.w,px-paddle.w/2));
}
cv.addEventListener('mousemove',function(e){
 var r=cv.getBoundingClientRect();
 if(state==='playing'||state==='idle'){if(paddle)movePaddleTo((e.clientX-r.left)*W/r.width);}
});
cv.addEventListener('touchmove',function(e){
 var r=cv.getBoundingClientRect();var t=e.touches[0];
 if(paddle)movePaddleTo((t.clientX-r.left)*W/r.width);e.preventDefault();
},{passive:false});
cv.addEventListener('mousedown',launch);
cv.addEventListener('touchstart',function(){launch();},{passive:true});
window.addEventListener('keydown',function(e){
 if(e.key==='ArrowLeft'||e.key==='a'||e.key==='A')keys.left=true;
 if(e.key==='ArrowRight'||e.key==='d'||e.key==='D')keys.right=true;
 if(e.key===' '){if(e.target!==btn){e.preventDefault();launch();}}
});
window.addEventListener('keyup',function(e){
 if(e.key==='ArrowLeft'||e.key==='a'||e.key==='A')keys.left=false;
 if(e.key==='ArrowRight'||e.key==='d'||e.key==='D')keys.right=false;
});
btn.addEventListener('click',start);
function update(){
 if(state!=='playing')return;
 if(keys.left)paddle.x=Math.max(0,paddle.x-6);
 if(keys.right)paddle.x=Math.min(W-paddle.w,paddle.x+6);
 if(ball.stuck){ball.x=paddle.x+paddle.w/2;ball.y=paddle.y-ball.r-1;return;}
 ball.x+=ball.vx;ball.y+=ball.vy;
 if(ball.x<ball.r){ball.x=ball.r;ball.vx=Math.abs(ball.vx);}
 if(ball.x>W-ball.r){ball.x=W-ball.r;ball.vx=-Math.abs(ball.vx);}
 if(ball.y<ball.r){ball.y=ball.r;ball.vy=Math.abs(ball.vy);}
 if(ball.vy>0&&ball.y+ball.r>=paddle.y&&ball.y+ball.r<=paddle.y+paddle.h+6&&ball.x>=paddle.x-ball.r&&ball.x<=paddle.x+paddle.w+ball.r){
  var rel=(ball.x-(paddle.x+paddle.w/2))/(paddle.w/2);
  var sp=Math.min(7,Math.sqrt(ball.vx*ball.vx+ball.vy*ball.vy)+0.05);
  var ang=rel*65*Math.PI/180;
  ball.vx=Math.sin(ang)*sp;ball.vy=-Math.cos(ang)*sp;
  ball.y=paddle.y-ball.r;
 }
 for(var i=0;i<bricks.length;i++){
  var b=bricks[i];
  if(ball.x+ball.r>b.x&&ball.x-ball.r<b.x+b.w&&ball.y+ball.r>b.y&&ball.y-ball.r<b.y+b.h){
   var ox=Math.min(ball.x+ball.r-b.x,b.x+b.w-(ball.x-ball.r));
   var oy=Math.min(ball.y+ball.r-b.y,b.y+b.h-(ball.y-ball.r));
   if(ox<oy)ball.vx=-ball.vx;else ball.vy=-ball.vy;
   b.hp--;score+=10;
   if(b.hp<=0){bricks.splice(i,1);score+=5;}
   hud();break;
  }
 }
 if(bricks.length===0){
  if(level>=LEVELS.length-1){state='won';setStatus('won','Grattis! Du klarade alla banor med '+score+' poäng! Tryck Starta om för att spela igen.');}
  else{level++;buildLevel(level);resetBall();hud();setStatus('playing','Bana '+(level+1)+' – klicka eller tryck mellanslag för att skjuta iväg bollen.');}
  return;
 }
 if(ball.y>H+20){
  lives--;hud();
  if(lives<=0){state='lost';setStatus('lost','Game over! Du fick '+score+' poäng. Tryck Starta om för att försöka igen.');}
  else{resetBall();setStatus('playing','Du tappade bollen! Liv kvar: '+lives+'. Klicka för att skjuta iväg.');}
 }
}
function draw(){
 ctx.clearRect(0,0,W,H);
 ctx.fillStyle='#0b1020';ctx.fillRect(0,0,W,H);
 if(!paddle){
  ctx.fillStyle='#8892b0';ctx.font='20px sans-serif';ctx.textAlign='center';
  ctx.fillText('Tryck på Starta spelet',W/2,H/2);return;
 }
 bricks.forEach(function(b){
  ctx.fillStyle=b.hp>1?'#adb5bd':RC[b.row%RC.length];
  ctx.fillRect(b.x,b.y,b.w,b.h);
  if(b.hp>1){ctx.strokeStyle='#fff';ctx.lineWidth=2;ctx.strokeRect(b.x+1,b.y+1,b.w-2,b.h-2);}
 });
 ctx.fillStyle='#ffd166';ctx.fillRect(paddle.x,paddle.y,paddle.w,paddle.h);
 ctx.beginPath();ctx.arc(ball.x,ball.y,ball.r,0,Math.PI*2);ctx.fillStyle='#fff';ctx.fill();
 if(state==='playing'&&ball.stuck){
  ctx.fillStyle='#c5cce2';ctx.font='16px sans-serif';ctx.textAlign='center';
  ctx.fillText('Klicka för att skjuta iväg',W/2,H/2+60);
 }
 if(state==='won'||state==='lost'){
  ctx.fillStyle='rgba(0,0,0,0.6)';ctx.fillRect(0,0,W,H);
  ctx.fillStyle='#fff';ctx.font='bold 30px sans-serif';ctx.textAlign='center';
  ctx.fillText(state==='won'?'Du vann!':'Game over',W/2,H/2);
 }
}
function loop(){update();draw();raf=requestAnimationFrame(loop);}
draw();
})();
